; EXPECT: pass
; NATIVE: yes
; V86: {"jit64_threshold": 10, "sync_jit": true}
; DESC: jit64: flags consumed after other instructions, across jumps, and by adc / inc / shifts (generated by gen_liveness.py)
%include "inc/long.inc"

test_main:
    xor r10d, r10d              ; number of mismatches
    ; cmp, then inc / dec / mov / lea, then jb
    lea rsi, [rel tbl1]
    mov ecx, 169
.l1:
    mov rax, [rsi]
    mov rbx, [rsi + 8]
    xor edx, edx
    cmp rax, rbx
    inc r12
    dec r8
    mov r9, rax
    lea r11, [rax + 1]
    jb .t1
    xor edx, edx
    jmp .e1
    .t1:
    mov edx, 1
    .e1:
    mov rdi, [rsi + 16]
    cmp rdx, rdi
    setne dil
    movzx edi, dil
    add r10, rdi
    add rsi, 24
    dec ecx
    jnz .l1
    CHECK_EQ 1, r10, 0
    ; cmp, jmp, then jl and je
    lea rsi, [rel tbl2]
    mov ecx, 169
.l2:
    mov rax, [rsi]
    mov rbx, [rsi + 8]
    xor edx, edx
    cmp rax, rbx
    jmp .b2
    .b2:
    mov rdx, 0
    jl .lt2
    je .eq2
    jmp .e2
    .lt2:
    mov edx, 1
    jmp .e2
    .eq2:
    mov edx, 2
    .e2:
    mov rdi, [rsi + 16]
    cmp rdx, rdi
    setne dil
    movzx edi, dil
    add r10, rdi
    add rsi, 24
    dec ecx
    jnz .l2
    CHECK_EQ 2, r10, 0
    ; add, sub, xor, inc, then cmp decides
    lea rsi, [rel tbl3]
    mov ecx, 169
.l3:
    mov rax, [rsi]
    mov rbx, [rsi + 8]
    xor edx, edx
    add rax, rbx
    sub rax, 5
    xor rax, rbx
    inc rax
    neg r12
    cmp rax, rbx
    setb dl
    movzx edx, dl
    mov rdi, [rsi + 16]
    cmp rdx, rdi
    setne dil
    movzx edi, dil
    add r10, rdi
    add rsi, 24
    dec ecx
    jnz .l3
    CHECK_EQ 3, r10, 0
    ; add, mov, lea, adc
    lea rsi, [rel tbl4]
    mov ecx, 169
.l4:
    mov rax, [rsi]
    mov rbx, [rsi + 8]
    xor edx, edx
    xor r12d, r12d
    add rax, rbx
    mov r8, 7
    lea r9, [r8 + r8]
    adc r12, 0
    mov rdx, r12
    mov rdi, [rsi + 16]
    cmp rdx, rdi
    setne dil
    movzx edi, dil
    add r10, rdi
    add rsi, 24
    dec ecx
    jnz .l4
    CHECK_EQ 4, r10, 0
    ; add, inc, jc and jz after inc
    lea rsi, [rel tbl5]
    mov ecx, 169
.l5:
    mov rax, [rsi]
    mov rbx, [rsi + 8]
    xor edx, edx
    add rax, rbx
    sbb rdx, rdx
    neg rdx
    inc rax
    setz r12b
    movzx r12d, r12b
    lea rdx, [rdx + r12*2]
    mov rdi, [rsi + 16]
    cmp rdx, rdi
    setne dil
    movzx edi, dil
    add r10, rdi
    add rsi, 24
    dec ecx
    jnz .l5
    CHECK_EQ 5, r10, 0
    ; shl / shr / sar and the carry flag
    lea rsi, [rel tbl6]
    mov ecx, 169
.l6:
    mov rax, [rsi]
    mov rbx, [rsi + 8]
    xor edx, edx
    shl rax, 3
    setc r12b
    shr rbx, 5
    setc r13b
    movzx edx, r12b
    movzx r13d, r13b
    lea rdx, [rdx + r13*2]
    mov rdi, [rsi + 16]
    cmp rdx, rdi
    setne dil
    movzx edi, dil
    add r10, rdi
    add rsi, 24
    dec ecx
    jnz .l6
    CHECK_EQ 6, r10, 0
    ; sar then sign and zero
    lea rsi, [rel tbl7]
    mov ecx, 169
.l7:
    mov rax, [rsi]
    mov rbx, [rsi + 8]
    xor edx, edx
    sar rax, 7
    sets r12b
    setz r13b
    movzx edx, r12b
    movzx r13d, r13b
    lea rdx, [rdx + r13*2]
    mov rdi, [rsi + 16]
    cmp rdx, rdi
    setne dil
    movzx edi, dil
    add r10, rdi
    add rsi, 24
    dec ecx
    jnz .l7
    CHECK_EQ 7, r10, 0
    ; cmp, memory access, call, jae
    lea rsi, [rel tbl8]
    mov ecx, 169
.l8:
    mov rax, [rsi]
    mov rbx, [rsi + 8]
    xor edx, edx
    cmp rax, rbx
    mov rdi, [rel scratch]
    mov [rel scratch], rdi
    lea r8, [rel scratch]
    jae .ae8
    xor edx, edx
    jmp .e8
    .ae8:
    mov edx, 1
    .e8:
    mov rdi, [rsi + 16]
    cmp rdx, rdi
    setne dil
    movzx edi, dil
    add r10, rdi
    add rsi, 24
    dec ecx
    jnz .l8
    CHECK_EQ 8, r10, 0
    PASS
